-- orders columns: order_id, customer_id, delivery_time_minutes, order_date, region, amount, city
-- customers columns: customer_id, name, city

-- Query 1: orders from Lagos customers (use IN with a subquery)
SELECT order_id, customer_id FROM orders ORDER BY order_id;

-- Query 2: orders above average delivery time (use a scalar subquery with AVG)
SELECT order_id, delivery_time_minutes FROM orders ORDER BY order_id;

